/* Mana Chat — website assistant + lead capture.
 * Knowledge base: assets/chat-kb.js (generated by build.py from the site's own data — do not hand-edit).
 * Leads: POSTed to KB.endpoint (Google Apps Script, tools/lead-collector.gs) when set, and always
 * offered as a pre-filled WhatsApp message to the hospital.
 * No AI service, no cookies; chat state lives in sessionStorage, ad attribution in localStorage.
 */
(function () {
  'use strict';
  var KB = window.MANA_KB;
  if (!KB || document.getElementById('mchat')) return;

  /* ------------------------------------------------------------ utils */
  var $ = function (s, r) { return (r || document).querySelector(s); };
  var esc = function (s) {
    return String(s == null ? '' : s).replace(/[&<>"']/g, function (c) {
      return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c];
    });
  };
  var store = {
    get: function (k, d, ls) { try { var v = (ls ? localStorage : sessionStorage).getItem(k); return v ? JSON.parse(v) : d; } catch (e) { return d; } },
    set: function (k, v, ls) { try { (ls ? localStorage : sessionStorage).setItem(k, JSON.stringify(v)); } catch (e) {} }
  };
  var norm = function (s) {
    return ' ' + String(s || '').toLowerCase().replace(/&amp;/g, '&').replace(/[^a-z0-9ఀ-౿+ ]+/g, ' ').replace(/\s+/g, ' ').trim() + ' ';
  };
  var track = function (name, data) {
    try { (window.dataLayer = window.dataLayer || []).push(Object.assign({ event: name }, data || {})); } catch (e) {}
    try { if (window.fbq && name === 'mana_chat_lead') window.fbq('track', 'Lead', { content_name: 'Mana Chat' }); } catch (e) {}
    try { if (window.gtag) window.gtag('event', name, data || {}); } catch (e) {}
  };

  /* ------------------------------------------------ ad attribution (first touch) */
  (function () {
    var q = new URLSearchParams(location.search), keys = ['utm_source', 'utm_medium', 'utm_campaign', 'utm_content', 'utm_term', 'gclid', 'gbraid', 'wbraid', 'fbclid', 'msclkid'];
    var a = store.get('mana_attr', null, true);
    var hit = keys.some(function (k) { return q.get(k); });
    if (!a || hit) {
      a = { landing: location.pathname, referrer: document.referrer || '', first_touch: new Date().toISOString() };
      keys.forEach(function (k) { if (q.get(k)) a[k] = q.get(k); });
      store.set('mana_attr', a, true);
    }
  })();

  /* ------------------------------------------------ page context */
  var page = (location.pathname.split('/').pop() || 'index.html').replace(/\.html$/, '');
  var ctxDept = KB.depts.filter(function (d) { return d.slug === page; })[0] || null;
  var ctxDoc = KB.doctors.filter(function (d) { return d.url === page + '.html'; })[0] || null;

  /* ------------------------------------------------ DOM */
  var root = document.createElement('div');
  root.id = 'mchat';
  root.innerHTML =
    '<button class="mc-fab" type="button" aria-label="Chat with Mana Hospitals" aria-expanded="false">' +
      '<span class="mc-fab-ic" aria-hidden="true"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M21 12a8 8 0 0 1-11.6 7.1L4 20l1-4.6A8 8 0 1 1 21 12Z"/><path d="M8.5 11h.01M12 11h.01M15.5 11h.01"/></svg></span>' +
      '<span class="mc-fab-x" aria-hidden="true"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round"><path d="M6 6l12 12M18 6 6 18"/></svg></span>' +
      '<span class="mc-dot" aria-hidden="true"></span>' +
    '</button>' +
    '<div class="mc-nudge" role="status" hidden><button class="mc-nudge-x" type="button" aria-label="Dismiss">×</button><b>Hi! 👋</b> Need help choosing a doctor or booking a visit?</div>' +
    '<section class="mc-panel" role="dialog" aria-modal="false" aria-label="Mana Hospitals assistant" hidden>' +
      '<header class="mc-head">' +
        '<span class="mc-av"><img src="assets/icons/icon-192.png" alt="" width="40" height="40"></span>' +
        '<div><b>Mana Assistant</b><small><i class="mc-live"></i>Replies instantly · Gajularamaram</small></div>' +
        '<a class="mc-hcall" href="tel:' + esc(KB.contact.tel) + '" aria-label="Call reception">' +
          '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M22 16.9v3a2 2 0 0 1-2.2 2 19.8 19.8 0 0 1-8.6-3.1 19.5 19.5 0 0 1-6-6A19.8 19.8 0 0 1 2.1 4.2 2 2 0 0 1 4.1 2h3a2 2 0 0 1 2 1.7c.1 1 .4 1.9.7 2.8a2 2 0 0 1-.5 2.1L8.1 9.9a16 16 0 0 0 6 6l1.3-1.3a2 2 0 0 1 2.1-.4c.9.3 1.8.6 2.8.7a2 2 0 0 1 1.7 2Z"/></svg></a>' +
        '<button class="mc-close" type="button" aria-label="Close chat"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round"><path d="M6 6l12 12M18 6 6 18"/></svg></button>' +
      '</header>' +
      '<div class="mc-log" aria-live="polite"></div>' +
      '<div class="mc-chips"></div>' +
      '<form class="mc-form" autocomplete="off">' +
        '<input class="mc-in" type="text" maxlength="300" placeholder="Type your question…" aria-label="Type your message">' +
        '<button class="mc-send" type="submit" aria-label="Send"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M5 12h14M13 6l6 6-6 6"/></svg></button>' +
      '</form>' +
      '<p class="mc-foot">For emergencies call <a href="tel:' + esc(KB.contact.emergTel) + '">' + esc(KB.contact.emerg) + '</a>. This assistant shares general information, not medical advice.</p>' +
    '</section>';
  document.body.appendChild(root);

  var fab = $('.mc-fab', root), panel = $('.mc-panel', root), log = $('.mc-log', root), chips = $('.mc-chips', root),
      form = $('.mc-form', root), input = $('.mc-in', root), nudge = $('.mc-nudge', root);

  /* ------------------------------------------------ state */
  var S = store.get('mana_chat', null) || { open: false, log: [], lead: null, step: null, asked: [], topics: [] };
  var save = function () { S.log = S.log.slice(-60); store.set('mana_chat', S); };

  function render(m) {
    var el = document.createElement('div');
    el.className = 'mc-msg ' + (m.me ? 'me' : 'bot');
    el.innerHTML = m.me ? esc(m.t) : m.h;
    log.appendChild(el);
    log.scrollTop = log.scrollHeight;
  }
  function say(html, opts) {
    var m = { h: html };
    S.log.push(m); save();
    var typing = document.createElement('div');
    typing.className = 'mc-msg bot mc-typing';
    typing.innerHTML = '<i></i><i></i><i></i>';
    log.appendChild(typing); log.scrollTop = log.scrollHeight;
    setTimeout(function () { typing.remove(); render(m); if (opts && opts.after) opts.after(); }, opts && opts.fast ? 150 : 450);
  }
  function me(text) { var m = { me: 1, t: text }; S.log.push(m); save(); render(m); }
  function setChips(list) {
    S.chips = list; save();
    chips.innerHTML = list.map(function (c, i) {
      return '<button type="button" class="mc-chip' + (c.primary ? ' pri' : '') + '" data-i="' + i + '">' + esc(c.label) + '</button>';
    }).join('');
    log.scrollTop = log.scrollHeight;
  }
  chips.addEventListener('click', function (e) {
    var b = e.target.closest('.mc-chip'); if (!b) return;
    var c = (S.chips || [])[+b.dataset.i]; if (!c) return;
    me(c.label); setChips([]); act(c.act, c.arg);
  });

  /* ------------------------------------------------ cards */
  var deptBy = {}; KB.depts.forEach(function (d) { deptBy[d.slug] = d; });
  var docBy = {}; KB.doctors.forEach(function (d) { docBy[d.name] = d; });

  function docCard(d) {
    var img = d.img ? '<img src="' + esc(d.img) + '" alt="" width="48" height="48" loading="lazy">' : '<span class="mc-ini">' + esc(d.ini) + '</span>';
    return '<a class="mc-card mc-doc" href="' + esc(d.url) + '">' + img + '<span><b>' + esc(d.name) + '</b><small>' + d.spec + '</small></span></a>';
  }
  function deptCard(d) {
    return '<a class="mc-card mc-dept" href="' + esc(d.url) + '"><img src="' + esc(d.img) + '" alt="" width="64" height="48" loading="lazy">' +
           '<span><b>' + d.name + '</b><small>View department →</small></span></a>';
  }

  /* ------------------------------------------------ menus */
  var MAIN = [
    { label: 'Book an appointment', act: 'book', primary: true },
    { label: 'Find a doctor', act: 'finddoc' },
    { label: 'Timings & location', act: 'where' },
    { label: 'Insurance / cashless', act: 'insurance' },
    { label: 'Emergency', act: 'emergency' }
  ];
  function mainChips(extra) { setChips((extra || []).concat(MAIN.filter(function (c) { return !(extra || []).some(function (x) { return x.act === c.act; }); })).slice(0, 6)); }

  function greet() {
    var h = 'Hi, I\'m the <b>Mana Hospitals</b> assistant. I can help you find the right doctor, check timings and insurance, or book a visit.';
    if (ctxDoc) h += '<br><br>Would you like to book a consultation with <b>' + esc(ctxDoc.name) + '</b>?';
    else if (ctxDept) h += '<br><br>Looking for <b>' + ctxDept.name + '</b>? I can get our team to call you with the next available slot.';
    say(h, { after: function () {
      var extra = [];
      if (ctxDoc) extra.push({ label: 'Book with ' + ctxDoc.short, act: 'book', arg: { doctor: ctxDoc.name, dept: ctxDoc.dept[0] }, primary: true });
      else if (ctxDept) extra.push({ label: 'Book ' + ctxDept.short, act: 'book', arg: { dept: ctxDept.slug }, primary: true });
      mainChips(extra);
    } });
  }

  /* ------------------------------------------------ actions */
  function act(a, arg) {
    if (a === 'book') return startLead(arg || {});
    if (a === 'finddoc') {
      say('Which kind of doctor do you need? Pick a department, or just type your problem (for example <i>knee pain</i> or <i>fever</i>).', { after: function () {
        setChips(KB.depts.slice(0, 9).map(function (d) { return { label: d.short, act: 'dept', arg: d.slug }; }).concat([{ label: 'More…', act: 'moredepts' }]));
      } });
      return;
    }
    if (a === 'moredepts') {
      say('Here are the rest:', { fast: true, after: function () {
        setChips(KB.depts.slice(9).map(function (d) { return { label: d.short, act: 'dept', arg: d.slug }; }));
      } });
      return;
    }
    if (a === 'dept') return answerDept(deptBy[arg]);
    if (a === 'doc') return answerDoc(docBy[arg]);
    if (a === 'where') return answerWhere();
    if (a === 'insurance') return answerInsurance();
    if (a === 'emergency') return answerEmergency();
    if (a === 'menu') return say('What else can I help with?', { fast: true, after: function () { mainChips(); } });
    if (a === 'wa') return openWA(arg);
    if (a === 'time') return leadTime(arg);
    if (a === 'consent') return submitLead();
    if (a === 'restart') { S.lead = null; S.step = null; save(); return startLead({}); }
  }

  function answerDept(d, why) {
    if (!d) return;
    S.topics.push(d.short); save();
    var docs = d.doctors.map(function (n) { return docBy[n]; }).filter(Boolean);
    var h = (why ? why + '<br><br>' : '') + '<b>' + d.name + '</b> — ' + d.lede +
            '<div class="mc-cards">' + deptCard(d) + docs.slice(0, 3).map(docCard).join('') + '</div>';
    say(h, { after: function () {
      next([{ label: 'Book ' + d.short, act: 'book', arg: { dept: d.slug }, primary: true },
                { label: 'Timings & location', act: 'where' }, { label: 'Insurance / cashless', act: 'insurance' }, { label: 'Something else', act: 'menu' }]);
    } });
  }
  function answerDoc(d) {
    if (!d) return;
    S.topics.push(d.name); save();
    say('<div class="mc-cards">' + docCard(d) + '</div>' + esc(d.name) + ' — ' + d.spec + (d.qual ? ' (' + d.qual + ')' : '') +
        '. Consultations are by appointment; the front desk will confirm the next available slot.', { after: function () {
      next([{ label: 'Book with ' + d.short, act: 'book', arg: { doctor: d.name, dept: d.dept[0] }, primary: true },
                { label: 'Timings & location', act: 'where' }, { label: 'Something else', act: 'menu' }]);
    } });
  }
  function answerWhere() {
    var c = KB.contact;
    say('<b>Mana Hospitals</b><br>' + c.address + '<br><br><b>OPD:</b> ' + KB.hours + '<br><b>Emergency &amp; ICU:</b> open 24×7' +
        '<div class="mc-acts"><a class="mc-btn" href="' + esc(c.maps) + '" target="_blank" rel="noopener">Get directions</a>' +
        '<a class="mc-btn ghost" href="tel:' + esc(c.tel) + '">Call ' + esc(c.phone) + '</a></div>', { after: function () {
      next([{ label: 'Book an appointment', act: 'book', primary: true }, { label: 'Find a doctor', act: 'finddoc' }, { label: 'Something else', act: 'menu' }]);
    } });
  }
  function answerInsurance() {
    say('Yes — we support <b>cashless</b> treatment and reimbursement claims. Our insurance desk verifies your policy, raises pre-authorisation and follows the claim to settlement.' +
        '<br><br><b>Insurers we work with include:</b> ' + KB.insurers.join(', ') + ', and major TPAs.' +
        '<br><br>Bring your policy card and a photo ID. Want us to check your policy before you come?', { after: function () {
      next([{ label: 'Yes, check my policy', act: 'book', arg: { concern: 'Insurance / cashless check' }, primary: true },
                { label: 'Find a doctor', act: 'finddoc' }, { label: 'Something else', act: 'menu' }]);
    } });
  }
  function answerEmergency() {
    var c = KB.contact;
    say('<div class="mc-emerg"><b>If this is an emergency, call now.</b> Our emergency department, ICU and NICU are open 24×7.' +
        '<a class="mc-btn red" href="tel:' + esc(c.emergTel) + '">Call emergency ' + esc(c.emerg) + '</a></div>' +
        'Or come straight to Plot No. 219, beside SBI Bank, Mahadevapuram Colony, Gajularamaram.', { after: function () {
      setChips([{ label: 'Get directions', act: 'where' }, { label: 'Something else', act: 'menu' }]);
    } });
    track('mana_chat_emergency');
  }

  /* ------------------------------------------------ free-text understanding */
  var EMERG = /\b(chest pain|heart attack|stroke|paralys|unconscious|not breathing|can ?t breathe|cannot breathe|breathless|severe bleeding|heavy bleeding|accident|seizure|fits|fainted|poison|suicide|burns?|snake ?bite|choking)\b/;
  var INTENTS = [
    [/\b(book|appointment|appoint|slot|consult(ation)?|visit|call ?back|callback|meet the doctor|op ticket)\b/, 'book'],
    [/\b(timing|timings|time|hours|open|close|closing|sunday|today open|working)\b/, 'where'],
    [/\b(where|address|location|located|direction|directions|route|map|landmark|parking|reach)\b/, 'where'],
    [/\b(insurance|cashless|tpa|claim|policy|mediclaim|aarogyasri|health card|cghs|esi)\b/, 'insurance'],
    [/\b(emergency|urgent|ambulance|casualty|icu)\b/, 'emergency'],
    [/\b(cost|price|charges?|fees?|rate|package|how much|estimate|bill)\b/, 'cost'],
    [/\b(doctor|doctors|specialist|consultant)s?\b/, 'finddoc'],
    [/\b(hi|hello|hey|namaste|namaskaram|good (morning|evening|afternoon))\b/, 'hello'],
    [/\b(thanks|thank you|thankyou|ok thanks|great)\b/, 'thanks']
  ];

  function scoreList(text, items, keyFn) {
    var best = null, top = 0;
    items.forEach(function (it) {
      var s = 0;
      keyFn(it).forEach(function (k) { if (k && text.indexOf(' ' + k + ' ') !== -1) s += k.split(' ').length * 2 + (k.length > 6 ? 1 : 0); });
      if (s > top) { top = s; best = it; }
    });
    return top ? { item: best, score: top } : null;
  }

  function understand(raw) {
    var t = norm(raw);
    S.asked.push(raw.slice(0, 140)); save();
    if (EMERG.test(t)) return answerEmergency();

    // in the middle of the lead form, treat text as the answer
    if (S.step === 'cname' || S.step === 'cphone') return contactInput(raw.trim());
    if (S.step) return leadInput(raw);

    var doc = scoreList(t, KB.doctors, function (d) { return d.kw; });
    if (doc && doc.score >= 2) return answerDoc(doc.item);

    var intent = null;
    for (var i = 0; i < INTENTS.length; i++) if (INTENTS[i][0].test(t)) { intent = INTENTS[i][1]; break; }
    var dept = scoreList(t, KB.depts, function (d) { return d.kw; });
    if (dept && dept.score < 2) dept = null;

    // children: route to Paediatrics whatever the symptom
    if (/ (child|children|kid|kids|baby|infant|newborn|son|daughter|toddler|my boy|my girl) /.test(t) && deptBy.paediatrics) dept = { item: deptBy.paediatrics, score: 9 };
    // insurer names count as an insurance question
    if (!intent && KB.insurers.some(function (n) { return t.indexOf(' ' + norm(n).trim().split(' ')[0] + ' ') !== -1; }) && / (insurance|health|accept|cashless|card|policy|tie|covered|cover) /.test(t)) intent = 'insurance';
    // direct questions ("do you do IVF?") — a strong FAQ match wins over a department card
    var faq = scoreList(t, KB.faqs, function (f) { return f.kw; });
    var asks = /^ (do|does|is|are|can|will|what|which|when|how|where|why) /.test(t);
    // a question that contains every key word of one FAQ question is that FAQ
    var full = null;
    KB.faqs.forEach(function (f) {
      if (!f.kw.length) return;
      var hit = f.kw.filter(function (k) { return t.indexOf(' ' + k + ' ') !== -1; }).length;
      if (hit === f.kw.length && (!full || f.kw.length > full.kw.length)) full = f;
    });
    if (asks && full && intent !== 'book' && intent !== 'cost') faq = { item: full, score: 99 };
    if (asks && faq && faq.score >= 4 && (!dept || faq.score >= dept.score + 2) && intent !== 'book' && intent !== 'cost') {
      return say(faq.item.a + (faq.item.url ? ' <a href="' + esc(faq.item.url) + '">Read more →</a>' : ''), { after: function () {
        var c = [{ label: 'Book an appointment', act: 'book', arg: dept ? { dept: dept.item.slug } : {}, primary: true }];
        if (dept) c.push({ label: 'About ' + dept.item.short, act: 'dept', arg: dept.item.slug });
        c.push({ label: 'Ask something else', act: 'menu' });
        next(c);
      } });
    }

    if (intent === 'book') return startLead(dept ? { dept: dept.item.slug } : {});
    if (intent === 'cost') {
      var dc = dept ? dept.item : null;
      return say('Costs depend on the consultant, tests and treatment you need' + (dc ? ' in <b>' + dc.short + '</b>' : '') + ', so we don\'t quote fixed prices here. Our front desk will give you a clear estimate before anything starts — and cashless insurance is supported.', { after: function () {
        next([{ label: 'Get a call with an estimate', act: 'book', arg: dc ? { dept: dc.slug, concern: 'Cost estimate — ' + dc.short } : { concern: 'Cost estimate' }, primary: true },
                  { label: 'Insurance / cashless', act: 'insurance' }, { label: 'Something else', act: 'menu' }]);
      } });
    }
    if (dept && dept.score >= 2) return answerDept(dept.item, dept.item.why || 'That sounds like something our <b>' + dept.item.short + '</b> team handles.');
    if (intent === 'emergency') return answerEmergency();
    if (intent === 'insurance') return answerInsurance();
    if (intent === 'where') return answerWhere();
    if (intent === 'finddoc') return act('finddoc');
    if (faq && faq.score >= 4) {
      return say(faq.item.a + (faq.item.url ? ' <a href="' + esc(faq.item.url) + '">Read more →</a>' : ''), { after: function () {
        next([{ label: 'Book an appointment', act: 'book', primary: true }, { label: 'Ask something else', act: 'menu' }]);
      } });
    }
    if (intent === 'hello') return say('Hello! How can I help you today?', { fast: true, after: function () { mainChips(); } });
    if (intent === 'thanks') return say('You\'re welcome. Take care! If you need anything else, I\'m right here.', { fast: true, after: function () { mainChips(); } });

    say('I\'m not sure I have the right answer for that. The quickest way is to have our team call you — it takes 20 seconds to request.', { after: function () {
      next([{ label: 'Request a call back', act: 'book', arg: { concern: raw.slice(0, 120) }, primary: true },
                { label: 'Call ' + KB.contact.phone, act: 'wa', arg: 'call' }, { label: 'Show options', act: 'menu' }]);
    } });
  }


  /* ------------------------------------------------ contact gate: after the first answer, ask name + mobile, then push a call */
  var CALL_CHIP = { label: '📞 Call now', act: 'wa', arg: 'call', primary: true };
  function next(list) {
    if (S.contact) return setChips([CALL_CHIP].concat(list.map(function (x) { return Object.assign({}, x, { primary: false }); })).slice(0, 5));
    if (S.step) return setChips(list);
    return askContact(list);
  }
  function askContact(pending) {
    S.pending = pending; S.step = 'cname'; save();
    track('mana_chat_contact_ask');
    say('So our care team can help you properly, may I have your <b>name</b>? 🙂', { after: function () {
      setChips([{ label: '📞 Call instead', act: 'wa', arg: 'call' }]);
      input.placeholder = 'Your name'; input.focus();
    } });
  }
  function looksLikeQuestion(v) {
    return /\?/.test(v) || v.split(/\s+/).length > 4 ||
      /^(do|does|is|are|can|what|which|when|how|where|why|i want|i need|my )/i.test(v.trim());
  }
  function contactInput(v) {
    if (S.step === 'cname') {
      if (looksLikeQuestion(v)) { S.deferQ = v; save(); return say('I\'ll answer that right away — first, may I have your <b>name</b>?', { fast: true }); }
      if (v.length < 2 || /\d{4,}/.test(v)) return say('Please type your name (for example <i>Ravi Kumar</i>).', { fast: true });
      S.contactName = v.replace(/\s+/g, ' ').slice(0, 60); S.step = 'cphone'; save();
      return say('Thanks, ' + esc(S.contactName.split(' ')[0]) + '! And your <b>mobile number</b>? Our team will call you back with the right doctor and the next available slot.', { after: function () {
        setChips([{ label: '📞 Call instead', act: 'wa', arg: 'call' }]);
        input.placeholder = '10-digit mobile number'; input.setAttribute('inputmode', 'tel'); input.focus();
      } });
    }
    if (S.step === 'cphone') {
      var d = v.replace(/\D/g, '').replace(/^(91|0)(?=\d{10}$)/, '');
      if (!/^[6-9]\d{9}$/.test(d)) return say('That doesn\'t look like a 10-digit mobile number. Could you check it?', { fast: true });
      S.contact = { name: S.contactName, phone: d }; S.step = null; save();
      input.removeAttribute('inputmode'); input.placeholder = 'Type your question…';
      submitEnquiry();
      return insistCall();
    }
  }
  function payloadBase(extra) {
    var a = store.get('mana_attr', {}, true);
    return Object.assign({}, a, {
      questions: S.asked.slice(-8).join(' | '), topics: S.topics.slice(-8).join(', '),
      page: location.pathname, device: /Mobi|Android/i.test(navigator.userAgent) ? 'mobile' : 'desktop',
      consent: 'yes — shared in chat ' + new Date().toISOString()
    }, extra);
  }
  function post(payload) {
    if (!KB.endpoint) return;
    try { fetch(KB.endpoint, { method: 'POST', mode: 'no-cors', headers: { 'Content-Type': 'text/plain;charset=utf-8' }, body: JSON.stringify(payload), keepalive: true }); } catch (e) {}
  }
  function submitEnquiry() {
    var c = S.contact, topic = S.topics[S.topics.length - 1] || '';
    var dm = KB.depts.filter(function (x) { return x.short === topic; })[0];
    post(payloadBase({ id: 'mc-' + Date.now().toString(36) + Math.random().toString(36).slice(2, 6), name: c.name, phone: c.phone,
      department: dm ? dm.short : '', doctor: docBy[topic] ? topic : '', concern: S.asked[0] || topic || 'Chat enquiry',
      callback_time: 'Call back — chat enquiry', source_form: 'mana-chat-enquiry' }));
    track('mana_chat_lead', { type: 'contact', dept: dm ? dm.short : '' });
  }
  function enquiryMessage() {
    var c = S.contact;
    return 'Hello Mana Hospitals, I have a query from your website chat.\nName: ' + c.name + '\nMobile: ' + c.phone +
           (S.asked.length ? '\nQuestion: ' + S.asked[0] : '') + (S.topics.length ? '\nAbout: ' + S.topics.slice(-3).join(', ') : '') +
           '\nPlease call me back.';
  }
  function insistCall() {
    var c = S.contact, k = KB.contact;
    say('<div class="mc-callcard"><b>Thank you, ' + esc(c.name.split(' ')[0]) + '!</b> The quickest way to get the right help is a 2-minute call — our front desk is available now and can book you in straight away.' +
        '<a class="mc-btn call" href="tel:' + esc(k.tel) + '" data-call>📞 Call now · ' + k.tel.slice(-10).replace(/(\d{5})(\d{5})/, '$1 $2') + '</a>' +
        '<a class="mc-btn green" href="' + waLink(enquiryMessage()) + '" target="_blank" rel="noopener" data-wa>Or send on WhatsApp</a></div>' +
        (KB.endpoint ? 'We\'ve noted <b>' + esc(c.phone) + '</b> — if you can\'t call now, we\'ll call you back shortly.' : 'Can\'t call right now? Tap <b>WhatsApp</b> and we\'ll call you back.'),
      { after: function () {
        var p = S.pending || []; S.pending = null; save();
        setChips([CALL_CHIP].concat(p.filter(function (x) { return !x.primary; }).slice(0, 3)));
        root.classList.add('called');
        if (S.deferQ) { var q = S.deferQ; S.deferQ = null; save(); setTimeout(function () { understand(q); }, 700); }
      } });
    track('mana_chat_contact');
  }

  /* ------------------------------------------------ lead capture */
  function startLead(pre) {
    S.lead = Object.assign({ dept: '', doctor: '', concern: '' }, S.lead && !S.lead.done ? S.lead : {}, pre);
    if (pre.dept && deptBy[pre.dept] && !S.lead.concern) S.lead.concern = deptBy[pre.dept].short;
    if (S.contact && !S.lead.phone) { S.lead.name = S.contact.name; S.lead.phone = S.contact.phone; }
    if (S.step === 'cname' || S.step === 'cphone') S.step = null;
    save();
    track('mana_chat_book_start', { dept: S.lead.dept || '', doctor: S.lead.doctor || '' });
    if (S.lead.name && S.lead.phone) return askConcern();
    S.step = 'name'; save();
    var what = S.lead.doctor ? ' with <b>' + esc(S.lead.doctor) + '</b>' : (S.lead.dept && deptBy[S.lead.dept] ? ' in <b>' + deptBy[S.lead.dept].name + '</b>' : '');
    say('Great — let\'s book your visit' + what + '. Our front desk will call to confirm the slot.<br><br>May I have the <b>patient\'s name</b>?', { after: function () {
      setChips([]); input.placeholder = 'Patient name'; input.focus();
    } });
  }
  function leadInput(raw) {
    var v = raw.trim();
    if (S.step === 'name') {
      if (v.length < 2 || /\d{5,}/.test(v)) return say('Please type the patient\'s name (for example <i>Ravi Kumar</i>).', { fast: true });
      S.lead.name = v.replace(/\s+/g, ' ').slice(0, 60); S.step = 'phone'; save();
      return say('Thanks, ' + esc(S.lead.name.split(' ')[0]) + '. What\'s the best <b>mobile number</b> to reach you?', { after: function () {
        input.placeholder = '10-digit mobile number'; input.setAttribute('inputmode', 'tel'); input.focus();
      } });
    }
    if (S.step === 'phone') {
      var d = v.replace(/\D/g, '').replace(/^(91|0)(?=\d{10}$)/, '');
      if (!/^[6-9]\d{9}$/.test(d)) return say('That doesn\'t look like a 10-digit Indian mobile number. Could you check it?', { fast: true });
      S.lead.phone = d; S.step = null; S.contact = S.contact || { name: S.lead.name, phone: d }; save();
      input.removeAttribute('inputmode'); input.placeholder = 'Type your question…';
      return askConcern();
    }
    if (S.step === 'concern') {
      S.lead.concern = v.slice(0, 200); S.step = null; save();
      var dm = scoreList(norm(v), KB.depts, function (x) { return x.kw; });
      if (dm && !S.lead.dept) { S.lead.dept = dm.item.slug; save(); }
      return askTime();
    }
  }
  function askConcern() {
    if (S.lead.concern || S.lead.doctor) return askTime();
    S.step = 'concern'; save();
    say('What would you like to see a doctor for? Type it in a few words, or pick a department.', { after: function () {
      setChips(KB.depts.slice(0, 8).map(function (d) { return { label: d.short, act: 'time', arg: { dept: d.slug } }; }));
      input.placeholder = 'e.g. knee pain, fever, pregnancy check-up'; input.focus();
    } });
  }
  function askTime() {
    S.step = null; save();
    say('When would you like to come in?', { after: function () {
      setChips([{ label: 'Today', act: 'time', arg: { when: 'Today' } }, { label: 'Tomorrow', act: 'time', arg: { when: 'Tomorrow' } },
                { label: 'This week', act: 'time', arg: { when: 'This week' } }, { label: 'Just call me', act: 'time', arg: { when: 'Call me — flexible' } }]);
      input.placeholder = 'Type your question…';
    } });
  }
  function leadTime(arg) {
    if (arg.dept) { S.lead.dept = arg.dept; S.lead.concern = S.lead.concern || deptBy[arg.dept].short; S.step = null; save(); return askTime(); }
    S.lead.when = arg.when; save();
    var L = S.lead, d = deptBy[L.dept];
    say('Please confirm:<div class="mc-sum">' +
        '<div><span>Patient</span><b>' + esc(L.name) + '</b></div>' +
        '<div><span>Mobile</span><b>' + esc(L.phone.replace(/(\d{5})(\d{5})/, '$1 $2')) + '</b></div>' +
        (L.doctor ? '<div><span>Doctor</span><b>' + esc(L.doctor) + '</b></div>' : '') +
        ((d || L.concern) ? '<div><span>For</span><b>' + esc(L.concern || d.short) + '</b></div>' : '') +
        '<div><span>When</span><b>' + esc(L.when) + '</b></div></div>' +
        '<small class="mc-consent">By sending, you agree that Mana Hospitals may call or WhatsApp you about this request. We use your details only to arrange your visit.</small>', { after: function () {
      setChips([{ label: 'Send request', act: 'consent', primary: true }, { label: 'Change details', act: 'restart' }]);
    } });
  }
  function leadMessage(L) {
    var d = deptBy[L.dept];
    return 'Hello Mana Hospitals, I would like to book an appointment.\n' +
           'Patient: ' + L.name + '\nMobile: ' + L.phone +
           (L.doctor ? '\nDoctor: ' + L.doctor : '') +
           ((L.concern || d) ? '\nFor: ' + (L.concern || d.short) : '') +
           '\nWhen: ' + L.when + '\n(Sent from the website chat)';
  }
  function submitLead() {
    var L = S.lead; if (!L || !L.phone) return startLead({});
    L.id = L.id || ('mc-' + Date.now().toString(36) + Math.random().toString(36).slice(2, 7));
    L.done = true; save();
    var a = store.get('mana_attr', {}, true), d = deptBy[L.dept];
    var payload = Object.assign({}, a, {
      id: L.id, name: L.name, phone: L.phone, department: d ? d.short : '', doctor: L.doctor || '', concern: L.concern || '',
      callback_time: L.when, questions: S.asked.slice(-8).join(' | '), topics: S.topics.slice(-8).join(', '),
      page: location.pathname, device: /Mobi|Android/i.test(navigator.userAgent) ? 'mobile' : 'desktop',
      consent: 'yes — ' + new Date().toISOString(), source_form: 'mana-chat'
    });
    post(payload);
    track('mana_chat_lead', { dept: payload.department, doctor: payload.doctor });
    var msg = KB.endpoint
      ? '✅ <b>Request received.</b> Our front desk will call ' + esc(L.name.split(' ')[0]) + ' on <b>' + esc(L.phone) + '</b> shortly' + (/today/i.test(L.when) ? ' to confirm a slot today' : '') + '.<br><br>Want a faster reply? Send it on WhatsApp too.'
      : 'Almost done — tap <b>Send on WhatsApp</b> to send your request to our front desk. They will reply and confirm your slot.';
    say(msg + '<div class="mc-acts"><a class="mc-btn green" href="' + waLink(leadMessage(L)) + '" target="_blank" rel="noopener" data-wa>Send on WhatsApp</a>' +
        '<a class="mc-btn ghost" href="tel:' + esc(KB.contact.tel) + '">Call now</a></div>', { after: function () {
      setChips([{ label: 'Ask something else', act: 'menu' }]);
    } });
  }
  function waLink(text) { return 'https://wa.me/' + KB.contact.wa + '?text=' + encodeURIComponent(text); }
  function openWA(arg) {
    if (arg === 'call') { track('mana_chat_call'); location.href = 'tel:' + KB.contact.tel; return; }
    window.open(waLink(arg || 'Hello Mana Hospitals'), '_blank', 'noopener');
  }
  log.addEventListener('click', function (e) { if (e.target.closest('[data-wa]')) track('mana_chat_whatsapp'); if (e.target.closest('[data-call]')) track('mana_chat_call'); });

  /* ------------------------------------------------ open / close */
  function open() {
    if (!panel.hidden) return;
    panel.hidden = false; root.classList.add('open'); fab.setAttribute('aria-expanded', 'true');
    nudge.hidden = true; S.open = true; S.seen = 1; save();
    if (!log.childElementCount) {
      if (S.log.length) { S.log.forEach(render); if (S.chips) setChips(S.chips); else mainChips(); }
      else greet();
    }
    track('mana_chat_open');
    setTimeout(function () { if (window.matchMedia('(min-width:721px)').matches) input.focus(); }, 250);
  }
  function close() { panel.hidden = true; root.classList.remove('open'); fab.setAttribute('aria-expanded', 'false'); S.open = false; save(); }
  fab.addEventListener('click', function () { panel.hidden ? open() : close(); });
  $('.mc-close', root).addEventListener('click', close);
  document.addEventListener('keydown', function (e) { if (e.key === 'Escape' && !panel.hidden) close(); });
  form.addEventListener('submit', function (e) {
    e.preventDefault();
    var v = input.value.trim(); if (!v) return;
    input.value = ''; me(v); setChips([]); understand(v);
  });
  nudge.addEventListener('click', function (e) {
    if (e.target.closest('.mc-nudge-x')) { nudge.hidden = true; store.set('mana_nudged', 1); return; }
    open();
  });
  // any "data-chat" link on the page opens the assistant
  document.addEventListener('click', function (e) {
    var t = e.target.closest('[data-chat]'); if (!t) return;
    e.preventDefault(); open();
  });

  if (S.open) open();
  else if (!store.get('mana_nudged') && !S.seen) {
    setTimeout(function () {
      if (panel.hidden && !store.get('mana_nudged')) { nudge.hidden = false; root.classList.add('nudging'); store.set('mana_nudged', 1); }
    }, 9000);
  }
})();
